#!/usr/bin/env python3
import os
import sys
import glob
import json
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta, timezone
import dateutil.parser
import re
import subprocess

def clean_html(text):
    if not text:
        return ""
    # Strip HTML tags
    text = re.sub(r'<[^>]+>', ' ', text)
    # Decode some basic <redacted> entities manually
    text = text.replace('&nbsp;', ' ')
    text = text.replace('&amp;', '&')
    text = text.replace('&lt;', '<')
    text = text.replace('&gt;', '>')
    text = text.replace('&quot;', '"')
    text = text.replace('&#039;', "'")
    text = text.replace('&#39;', "'")
    text = text.replace('&apos;', "'")
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def strip_google_news_redirect(url):
    if not url:
        return ""
    # Some google news redirects are complex, but let's check if we can get the real url
    return url.strip()

def parse_date(date_str):
    if not date_str:
        return None
    try:
        return dateutil.parser.parse(date_str)
    except Exception:
        return None

def is_meme_coin(headline, exclude_keywords):
    headline_lower = headline.lower()
    for kw in exclude_keywords:
        if re.search(r'\b' + re.escape(kw) + r'\b', headline_lower) or kw in headline_lower:
            return True
    return False

def calculate_overlap(h1, h2):
    # Overlap of significant words after lowercasing and stop-word removal
    stopwords = {'the', 'a', 'an', 'and', 'or', 'but', 'is', 'are', 'was', 'were', 'to', 'of', 'in', 'on', 'at', 'by', 'for', 'with', 'about', 'against', 'between', 'into', 'through', 'during', 'before', 'after', 'above', 'below', 'to', 'from', 'up', 'down', 'in', 'out', 'on', 'off', 'over', 'under', 'again', 'further', 'then', 'once'}
    w1 = set([w for w in re.findall(r'\w+', h1.lower()) if w not in stopwords])
    w2 = set([w for w in re.findall(r'\w+', h2.lower()) if w not in stopwords])
    if not w1 or not w2:
        return 0.0
    intersection = w1.intersection(w2)
    return len(intersection) / max(len(w1), len(w2))

def main():
    exclude_keywords = ["dogecoin", "shiba", "pepe", "floki", "bonk", "wif", "memecoin", "meme coin"]
    source_priority = ["CoinDesk", "CoinTelegraph", "Decrypt", "The Block", "BeInCrypto", "CryptoSlate", "CryptoFox", "Google News"]

    # Let's read project config to make sure we use actual config
    try:
        with open("/home/bhard/.openclaw/projects/coinography.json", "r") as f:
            project_cfg = json.load(f)
            exclude_keywords = project_cfg.get("research", {}).get("exclude_keywords", exclude_keywords)
            source_priority = project_cfg.get("research", {}).get("source_priority_order", source_priority)
    except Exception as e:
        print(f"Warning: could not load project config: {e}", file=sys.stderr)

    now = datetime.now(timezone.utc)
    one_day_ago = now - timedelta(hours=24)

    raw_items = []

    xml_files = sorted(glob.glob('/tmp/feeds/*.xml'))
    for xml_file in xml_files:
        source_file = xml_file.replace('.xml', '.source')
        source_name = "Unknown"
        if os.path.exists(source_file):
            with open(source_file, 'r') as sf:
                source_name = sf.read().strip()

        print(f"Parsing {xml_file} (Source: {source_name})...", file=sys.stderr)
        try:
            tree = ET.parse(xml_file)
            root = tree.getroot()
        except Exception as e:
            print(f"Error parsing {xml_file}: {e}", file=sys.stderr)
            continue

        items = root.findall('.//item')
        if not items:
            # Maybe Atom?
            items = root.findall('.//{http://www.w3.org/2005/Atom}entry')
            # For now, let's assume standard RSS as it's most common

        for idx, item in enumerate(items):
            title_el = item.find('title')
            link_el = item.find('link')
            pub_date_el = item.find('pubDate') or item.find('{http://purl.org/dc/elements/1.1/}date')
            desc_el = item.find('description') or item.find('summary')

            headline = clean_html(title_el.text) if title_el is not None and title_el.text else ""
            url = link_el.text.strip() if link_el is not None and link_el.text else ""
            if not url and link_el is not None:
                # Atom link might be in attrib
                url = link_el.attrib.get('href', '').strip()

            pub_date_str = pub_date_el.text.strip() if pub_date_el is not None and pub_date_el.text else ""
            summary = clean_html(desc_el.text)[:280] if desc_el is not None and desc_el.text else ""

            if not headline or not url:
                continue

            # Filters
            parsed_date = parse_date(pub_date_str)
            if parsed_date:
                # Ensure it is timezone-aware
                if parsed_date.tzinfo is None:
                    parsed_date = parsed_date.replace(tzinfo=timezone.utc)
                if parsed_date < one_day_ago:
                    continue
            else:
                # If we cannot parse date, keep only if it is in the first 5 of that feed
                if idx >= 5:
                    continue

            if is_meme_coin(headline, exclude_keywords):
                continue

            if url.startswith('mailto:') or url.startswith('javascript:') or not url:
                continue

            # Formatting parsed_date to ISO 8601 UTC
            if parsed_date:
                pub_date_iso = parsed_date.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
            else:
                pub_date_iso = pub_date_str # Fallback to raw if unparsable but kept

            raw_items.append({
                'headline': headline,
                'url': url,
                'pub_date': pub_date_iso,
                'pub_date_parsed': parsed_date,
                'source': source_name,
                'summary': summary,
                'corroborating_sources': []
            })

    print(f"Total raw items gathered: {len(raw_items)}", file=sys.stderr)

    # Sort raw items by source priority to make deduplication clean
    # Higher priority sources processed first
    def get_source_priority_index(item):
        src = item['source']
        if src in source_priority:
            return source_priority.index(src)
        return len(source_priority)

    raw_items.sort(key=get_source_priority_index)

    # Deduplicate URL and same-story
    unique_items = []
    seen_urls = set()

    for item in raw_items:
        # Check URL uniqueness
        if item['url'] in seen_urls:
            continue

        # Check same-story dedupe (overlap >= 80%)
        is_dup = False
        for unique_item in unique_items:
            overlap = calculate_overlap(item['headline'], unique_item['headline'])
            if overlap >= 0.8:
                # It is a duplicate. Add as corroborating source to the existing unique item
                # up to 2 corroborating sources
                if len(unique_item['corroborating_sources']) < 2:
                    # check if source is already added or is the same
                    existing_sources = [s['source'] for s in unique_item['corroborating_sources']]
                    if item['source'] != unique_item['source'] and item['source'] not in existing_sources:
                        unique_item['corroborating_sources'].append({
                            'source': item['source'],
                            'url': item['url']
                        })
                is_dup = True
                break

        if not is_dup:
            unique_items.append(item)
            seen_urls.add(item['url'])

    print(f"Items after deduplication: {len(unique_items)}", file=sys.stderr)

    # Check against persistent history database
    history_checked_items = []
    for item in unique_items:
        # Call article_history.sh check
        try:
            res = subprocess.run(
                ["bash", "/home/bhard/.openclaw/workspace-researcher/skills/history/article_history.sh", "check", item['url'], "--project", "coinography"],
                capture_output=True, text=True, check=True
            )
            status = res.stdout.strip()
            if status == "NOT_FOUND":
                history_checked_items.append(item)
            else:
                print(f"Dropped duplicate from history: {item['headline']} ({item['url']})", file=sys.stderr)
        except Exception as e:
            print(f"Error checking history for {item['url']}: {e}", file=sys.stderr)
            # Default to keeping it on error to be safe, or drop? Let's keep it.
            history_checked_items.append(item)

    print(f"Items after history check: {len(history_checked_items)}", file=sys.stderr)

    # Sort by pub_date desc
    # Handle items without parsable date gracefully (place after dated items)
    def sort_key(item):
        if item['pub_date_parsed']:
            return (1, item['pub_date_parsed'])
        else:
            return (0, datetime.min.replace(tzinfo=timezone.utc))

    history_checked_items.sort(key=sort_key, reverse=True)

    # Keep up to TARGET_COUNT
    target_count = 10
    if len(sys.argv) > 1:
        target_count = int(sys.argv[1])

    candidates = history_checked_items[:target_count]

    # Format candidates for JSON output (remove parsed datetime objects)
    formatted_candidates = []
    for idx, item in enumerate(candidates, 1):
        formatted_candidates.append({
            'candidate_index': idx,
            'headline': item['headline'],
            'url': item['url'],
            'pub_date': item['pub_date'],
            'source': item['source'],
            'summary': item['summary'],
            'corroborating_sources': item['corroborating_sources']
        })

    out_json = {
        'status': 'ok',
        'mode': 'headline_scan',
        'scanned_at': datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),
        'target_count': target_count,
        'candidate_count': len(formatted_candidates),
        'candidates': formatted_candidates
    }

    print(json.dumps(out_json, indent=2))

if __name__ == '__main__':
    main()

